class BundleConfig(BaseModelExtended):
    """Configuration for a single placement group resource bundle.

    ``CPU`` and ``GPU`` are first-class fields, but arbitrary additional named
    resources (e.g. ``TPU``) may be provided as extra keyword arguments. All
    resource counts are stored as floats to align with Ray resource typing, so
    integer inputs (e.g. ``CPU=2``) are coerced to floats.
    """

    # Allow arbitrary named resources (e.g. TPU) in addition to CPU/GPU.
    model_config = ConfigDict(
        protected_namespaces=tuple(),
        extra="allow",
    )

    CPU: float = Field(default=0.0, description="Number of CPUs per bundle")
    GPU: float = Field(default=0.0, description="Number of GPUs per bundle")

    @model_validator(mode="before")
    @classmethod
    def _validate_resources(cls, data: Any) -> Any:
        """Validate and normalize every resource value.

        Ensures each provided value is a non-negative number and coerces it to a
        float so it is emitted consistently in ``model_dump()``.
        """
        if not isinstance(data, dict):
            return data

        normalized = {}
        for key, value in data.items():
            # ``bool`` is a subclass of ``int`` but is not a valid resource count.
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"Resource '{key}' must be a number, got {value!r}."
                )
            if value < 0:
                raise ValueError(
                    f"Resource '{key}' must be non-negative, got {value}."
                )
            normalized[key] = float(value)
        return normalized


class PlacementGroupConfig(BaseModelExtended):
    """Configuration for a Ray placement group.

    Exactly one of ``bundles`` or ``bundle_per_worker`` must be provided. Raw
    dicts supplied for the bundle fields are automatically coerced into
    :class:`BundleConfig` instances.
    """

    bundles: Optional[List[BundleConfig]] = Field(
        default=None,
        description="Explicit list of resource bundles.",
    )
    bundle_per_worker: Optional[BundleConfig] = Field(
        default=None,
        description=(
            "Resource bundle specification for each worker. Auto-replicated "
            "based on tensor_parallel_size * pipeline_parallel_size. Cannot be "
            "used together with 'bundles'."
        ),
    )
    strategy: PlacementStrategy = Field(description="Placement group strategy.")

    @model_validator(mode="after")
    def _validate_bundle_options(self) -> "PlacementGroupConfig":
        if self.bundles is not None and self.bundle_per_worker is not None:
            raise ValueError(
                "Cannot specify both 'bundles' and 'bundle_per_worker'. Use "
                "'bundle_per_worker' for a simple per-worker resource "
                "specification (auto-replicated by tp*pp), or 'bundles' for "
                "full control."
            )
        if self.bundles is None and self.bundle_per_worker is None:
            raise ValueError(
                "Must specify either 'bundle_per_worker' or 'bundles'."
            )
        return self

    def model_dump(self, **kwargs) -> dict:
        data = super().model_dump(**kwargs)
        # Only emit the bundle field that was actually provided.
        if data.get("bundles") is None:
            data.pop("bundles", None)
        if data.get("bundle_per_worker") is None:
            data.pop("bundle_per_worker", None)
        return data
